/** An in-memory list of tasks. Ids start at 1 and are never reused. */
export function createStore() {
  const tasks = [];
  let nextId = 1;

  const PRIORITY_WEIGHTS = {
    high: 0,
    normal: 1,
    low: 2,
  };

  function find(id) {
    const task = tasks.find((t) => t.id === id);
    if (!task) throw new Error(`No task with id ${id}`);
    return task;
  }

  return {
    add(title, priority = "normal") {
      const trimmed = String(title ?? "").trim();
      if (trimmed === "") throw new Error("A task needs a title");
      const task = { id: nextId++, title: trimmed, priority, done: false };
      tasks.push(task);
      return { ...task };
    },

    complete(id) {
      const task = find(id);
      task.done = true;
      return { ...task };
    },

    remove(id) {
      const task = find(id);
      tasks.splice(tasks.indexOf(task), 1);
    },

    /**
     * Copies of every task, sorted by priority (High > Normal > Low),
     * then by original sequence.
     */
    all() {
      return [...tasks]
        .sort((a, b) => {
          const weightA = PRIORITY_WEIGHTS[a.priority] ?? 1;
          const weightB = PRIORITY_WEIGHTS[b.priority] ?? 1;
          return weightA - weightB;
        })
        .map((t) => ({ ...t }));
    },
  };
}

import { formatList } from "./format.js";

/**
 * Run one command against a store and return the text to print.
 *
 *   add <title...>   add a task
 *   done <id>        mark a task as done
 *   remove <id>      delete a task
 *   list             show every task
 */
export function run(args, store) {
  const [command, ...rest] = args;
  switch (command) {
    case "add": {
      const priorityIndex = rest.indexOf("--priority");
      let priority = "normal";
      let titleArgs = rest;

      if (priorityIndex !== -1) {
        const value = rest[priorityIndex + 1];
        const allowed = ["low", "normal", "high"];
        if (!value || !allowed.includes(value)) {
          throw new Error(`Invalid priority: ${value ?? "(missing)"}`);
        }
        priority = value;
        // Remove the --priority flag and its value from the title
        titleArgs = [
          ...rest.slice(0, priorityIndex),
          ...rest.slice(priorityIndex + 2),
        ];
      }

      const task = store.add(titleArgs.join(" "), priority);
      return `Added ${task.id}: ${task.title}`;
    }
    case "done": {
      const task = store.complete(parseId(rest[0]));
      return `Completed ${task.id}`;
    }
    case "remove": {
      const id = parseId(rest[0]);
      store.remove(id);
      return `Removed ${id}`;
    }
    case "list":
      return formatList(store.all());
    default:
      throw new Error(`Unknown command: ${command ?? "(none)"}`);
  }
}

function parseId(text) {
  const id = Number(text);
  if (!Number.isInteger(id) || id < 1) throw new Error(`Not a task id: ${text}`);
  return id;
}

import assert from 'node:assert';
import test from 'node:test';
import { saveTask, getTasks } from '../src/store.js';
import { formatTask } from '../src/format.js';

// Note: Tests are designed based on Architecture contracts
// src/store.js: saveTask(task, priority), getTasks()
// src/format.js: formatTask(task)

test('AC-1: default priority is normal', () => {
  // The CLI handler is responsible for the default, but we verify the store state
  // simulating the CLI passing 'normal' when flag is absent
  saveTask({ title: 'Default Task' }, 'normal');
  const tasks = getTasks();
  assert.strictEqual(tasks[0].priority, 'normal');
});

test('AC-2: add task with high priority', () => {
  saveTask({ title: 'High Task' }, 'high');
  const tasks = getTasks();
  assert.strictEqual(tasks[0].priority, 'high');
});

test('AC-3: add task with normal priority', () => {
  saveTask({ title: 'Normal Task' }, 'normal');
  const tasks = getTasks();
  assert.strictEqual(tasks[0].priority, 'normal');
});

test('AC-4: add task with low priority', () => {
  saveTask({ title: 'Low Task' }, 'low');
  const tasks = getTasks();
  assert.strictEqual(tasks[0].priority, 'low');
});

test('AC-6: tasks are sorted by priority High > Normal > Low', () => {
  // Clear store if possible or use unique titles
  saveTask({ title: 'Low' }, 'low');
  saveTask({ title: 'High' }, 'high');
  saveTask({ title: 'Normal' }, 'normal');

  const tasks = getTasks();
  assert.strictEqual(tasks[0].priority, 'high');
  assert.strictEqual(tasks[1].priority, 'normal');
  assert.strictEqual(tasks[2].priority, 'low');
});

test('AC-7: tasks of same priority maintain insertion order', () => {
  saveTask({ title: 'First High' }, 'high');
  saveTask({ title: 'Second High' }, 'high');
  saveTask({ title: 'First Low' }, 'low');
  saveTask({ title: 'Second Low' }, 'low');

  const tasks = getTasks();
  assert.strictEqual(tasks[0].title, 'First High');
  assert.strictEqual(tasks[1].title, 'Second High');
  assert.strictEqual(tasks[2].title, 'First Low');
  assert.strictEqual(tasks[3].title, 'Second Low');
});

test('AC-8: non-normal priorities display labels', () => {
  const highTask = { title: 'Task H', priority: 'high' };
  const lowTask = { title: 'Task L', priority: 'low' };

  assert.ok(formatTask(highTask).includes('(high)'));
  assert.ok(formatTask(lowTask).includes('(low)'));
});

test('AC-9: normal priority does not display label', () => {
  const normalTask = { title: 'Task N', priority: 'normal' };
  const formatted = formatTask(normalTask);

  assert.ok(!formatted.includes('(normal)'));
  assert.ok(!formatted.includes('(high)'));
  assert.ok(!formatted.includes('(low)'));
});

import assert from 'node:assert';
import test from 'node:test';
import { execSync } from 'node:child_process';

// These tests execute the CLI to verify AC-1 and AC-5 which happen in the CLI layer

test('AC-1: CLI adds normal priority when flag is omitted', () => {
  // We assume 'add' command exists. We check output or store state via list
  execSync('node src/cli.js add "No Priority Task"');
  const output = execSync('node src/cli.js list').toString();
  assert.ok(output.includes('No Priority Task') && !output.includes('(normal)'));
});

test('AC-5: CLI returns error for unsupported priority', () => {
  try {
    execSync('node src/cli.js add "Urgent Task" --priority urgent');
    assert.fail('Should have thrown an error');
  } catch (error) {
    assert.ok(true);
    const output = execSync('node src/cli.js list').toString();
    assert.ok(!output.includes('Urgent Task'), 'Task should not have been added to store');
  }
});

